/**
 * Quadratic extension Fp[u] / (u² - 7).
 *
 * The non-residue 7 is regenerated by
 * tools/reference.py. This module is intentionally DOM-free so the extension
 * arithmetic can be exercised under Vitest's node environment.
 */
import {
  P,
  add as addBase,
  inv as invBase,
  mul as mulBase,
  neg as negBase,
  pow as powBase,
  sub as subBase,
} from './field';
import type { Fp } from './field';

export interface Fp2 {
  /** a + b·u, where u² = 7. */
  c0: Fp;
  c1: Fp;
}

export const FP2_NON_RESIDUE = 7n;
export const fp2Zero: Fp2 = { c0: 0n, c1: 0n };
export const fp2One: Fp2 = { c0: 1n, c1: 0n };

export function fp2(c0: Fp, c1: Fp = 0n): Fp2 {
  return { c0, c1 };
}

export function embed(value: Fp): Fp2 {
  return { c0: value, c1: 0n };
}

export function equal(left: Fp2, right: Fp2): boolean {
  return left.c0 === right.c0 && left.c1 === right.c1;
}

export function isZero(value: Fp2): boolean {
  return value.c0 === 0n && value.c1 === 0n;
}

export function add(left: Fp2, right: Fp2): Fp2 {
  return { c0: addBase(left.c0, right.c0), c1: addBase(left.c1, right.c1) };
}

export function sub(left: Fp2, right: Fp2): Fp2 {
  return { c0: subBase(left.c0, right.c0), c1: subBase(left.c1, right.c1) };
}

export function neg(value: Fp2): Fp2 {
  return { c0: negBase(value.c0), c1: negBase(value.c1) };
}

/** (a + bu)(c + du) = (ac + 7bd) + (ad + bc)u. */
export function mul(left: Fp2, right: Fp2): Fp2 {
  return {
    c0: addBase(mulBase(left.c0, right.c0), mulBase(FP2_NON_RESIDUE, mulBase(left.c1, right.c1))),
    c1: addBase(mulBase(left.c0, right.c1), mulBase(left.c1, right.c0)),
  };
}

export function square(value: Fp2): Fp2 {
  return mul(value, value);
}

/** (a + bu)⁻¹ = (a - bu) / (a² - 7b²). */
export function inv(value: Fp2): Fp2 {
  const norm = subBase(
    mulBase(value.c0, value.c0),
    mulBase(FP2_NON_RESIDUE, mulBase(value.c1, value.c1)),
  );
  if (norm === 0n) throw new Error('fp2.inv(0)');
  const normInverse = invBase(norm);
  return { c0: mulBase(value.c0, normInverse), c1: mulBase(negBase(value.c1), normInverse) };
}

export function div(left: Fp2, right: Fp2): Fp2 {
  return mul(left, inv(right));
}

export function pow(base: Fp2, exponent: bigint): Fp2 {
  if (exponent < 0n) throw new Error('fp2.pow requires a non-negative exponent');
  let value = base;
  let power = exponent;
  let result = fp2One;
  while (power > 0n) {
    if ((power & 1n) === 1n) result = mul(result, value);
    value = square(value);
    power >>= 1n;
  }
  return result;
}

/** Frobenius conjugation in this quadratic extension. */
export function conjugate(value: Fp2): Fp2 {
  return { c0: value.c0, c1: negBase(value.c1) };
}

/** A deterministic, canonical wire representation used by transcript adapters. */
export function toTuple(value: Fp2): readonly [Fp, Fp] {
  return [value.c0, value.c1];
}

export function isCanonical(value: Fp2): boolean {
  return value.c0 >= 0n && value.c0 < P && value.c1 >= 0n && value.c1 < P;
}

export function format(value: Fp2): string {
  return value.c1 === 0n ? value.c0.toString() : `${value.c0} + ${value.c1}u`;
}

/**
 * Validates the defining polynomial with the base-field Euler criterion.
 * Keeping this executable makes the extension's irreducibility assumption a
 * gate rather than an undocumented constant.
 */
export function nonResidueIsValid(): boolean {
  return powBase(FP2_NON_RESIDUE, (P - 1n) >> 1n) === P - 1n;
}
